// Browser application. Kept separate from the HTML shell and design tokens.
export function serviceApp(){
  'use strict';
  const $=id=>document.getElementById(id),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const paths={overview:'M3 11 12 4l9 7M5 10v10h14V10M10 20v-6h4v6',diagnostics:'M4 12h4l3-8 3 16 3-8h3',requests:'M4 4h16v13H9l-5 4V4M8 8h8M8 12h5',leads:'M7 3h10v18H7zM10 8h4M10 12h4M10 16h2',reviews:'m12 3 3 6 6 1-4 4 1 7-6-3-6 3 1-7-4-4 6-1z',settings:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6',clients:'M4 21v-3a5 5 0 0 1 10 0v3M19 21v-3a4 4 0 0 0-3-4M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8',check:'m5 12 4 4 10-10',arrow:'M5 12h14m-5-5 5 5-5 5',external:'M13 4h7v7M20 4 10 14M10 4H4v16h16v-6',menu:'M4 6h16M4 12h16M4 18h16',logout:'M9 4H4v16h5M10 12h10m-4-4 4 4-4 4',plus:'M12 4v16M4 12h16',clock:'M12 7v5l3 2M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',alert:'m12 3 10 18H2zM12 9v5M12 17v1',billing:'M3 5h18v14H3zM3 10h18M7 15h4',link:'m9 15 6-6M7 14H6a4 4 0 0 1 0-8h4M14 18h4a4 4 0 0 0 0-8h-1',refresh:'M20 7v5h-5M4 17v-5h5M5 8a8 8 0 0 1 14-2l1 6M4 12l1 6a8 8 0 0 0 14-2'};
  const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.overview}"/></svg>`;
  const statusNames={new:'Получено',quoted:'На согласовании',approved:'Согласовано',in_progress:'В работе',waiting_client:'Нужен ваш ответ',completed:'Завершено',canceled:'Отменено',problem:'Подтверждённый ответ',review:'Нужна проверка',improvement:'Улучшение',outdated:'Нужно обновить',ok:'Подтверждено'};
  const categoryNames={seo:'Поиск',content:'Содержимое',accessibility:'Удобство',mobile:'Мобильная версия',security:'Ресурсы',performance:'Время ответа',social:'Превью ссылок',availability:'Доступность'};
  const badge=(status,label)=>`<span class="badge ${h(status)}">${h(label||statusNames[status]||status)}</span>`;
  const money=v=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:2}).format(Number(v)/100);
  const date=v=>v&&Number.isFinite(Date.parse(v))?new Date(v).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'Ещё нет данных';
  const metric=(label,value,note)=>`<div class="metric"><span class="metric-label">${h(label)}</span><strong>${h(value)}</strong><small>${h(note)}</small></div>`;
  const field=(name,label,value='',type='text',hint='')=>`<div class="field"><label for="f-${h(name)}">${h(label)}</label>${type==='textarea'?`<textarea id="f-${h(name)}" name="${h(name)}" required maxlength="4000">${h(value)}</textarea>`:`<input id="f-${h(name)}" name="${h(name)}" type="${h(type)}" value="${h(value)}" required ${type==='password'?'autocomplete="new-password"':''}>`}${hint?`<small>${h(hint)}</small>`:''}</div>`;
  const selectField=(name,label,options,value)=>`<div class="field"><label for="f-${h(name)}">${h(label)}</label><select id="f-${h(name)}" name="${h(name)}">${options.map(([v,l])=>`<option value="${h(v)}" ${v===value?'selected':''}>${h(l)}</option>`).join('')}</select></div>`;
  const button=(label,action,extra='',secondary=false)=>`<button type="button" class="button ${secondary?'secondary':''}" data-action="${h(action)}" ${extra}>${h(label)}</button>`;
  const link=(label,view,secondary=true)=>`<a class="button ${secondary?'secondary':''}" href="#${h(view)}">${h(label)}</a>`;
  const empty=(title,copy,actions='')=>`<div class="empty">${icon('requests')}<h3>${h(title)}</h3><p>${h(copy)}</p>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
  const pageHead=(title,description,actions='')=>`<header class="page-head"><div><div class="eyebrow">${isSpecialist()?'Рабочий кабинет':'Сопровождение сайта'}</div><h1 tabindex="-1">${h(title)}</h1>${description?`<p>${h(description)}</p>`:''}</div><div class="actions">${actions}</div></header>`;
  function safeUrl(v){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return '';}}
  const external=(url,label)=>safeUrl(url)?`<a href="${h(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${h(label)} ${icon('external')}</a>`:h(label);
  let state=null,csrf='',accountId='',siteId='',care=null,report=null,queue=[],reviews=null,detail=null,renderId=0,filter='all',search='',leadRows=[],leadCursor=null,leadMore=false;
  let selectedRequest='',dialogReturnFocus=null,toastTimer;
  const isSpecialist=()=>state?.user.platform_role==='operator';
  const account=()=>state?.accounts.find(a=>a.account_id===accountId)||state?.accounts[0];
  const site=()=>account()?.sites.find(s=>s.site_id===siteId)||account()?.sites[0];
  const canManage=()=>isSpecialist()||['owner','admin','manager'].includes(account()?.role);
  const enabled=key=>Boolean(account()?.features?.[key]?.enabled);
  const siteApi=tail=>'/v1/platform/sites/'+encodeURIComponent(siteId)+tail;
  const closed=r=>['completed','canceled'].includes(r.status);
  function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('toast').hidden=true;},6000);}
  async function api(path,method='GET',body){
    const response=await fetch(path,{method,credentials:'same-origin',headers:{...(method==='GET'?{}:{'Content-Type':'application/json','X-SiteCare-CSRF':csrf})},...(body===undefined?{}:{body:JSON.stringify(body)})});
    let data;try{data=await response.json();}catch{throw new Error('Сервер вернул неожиданный ответ. Повторите запрос.');}
    if(!response.ok){if(response.status===401){state=null;showLogin();}throw Object.assign(new Error(data.error?.message||data.message||(typeof data.error==='string'?data.error:'Не удалось выполнить запрос.')),{status:response.status});}
    return data;
  }
  function showLogin(){$('shell').hidden=true;$('login').hidden=false;}
  async function loadDashboard(preferred=accountId){
    state=await api('/v1/platform/dashboard'+(preferred?'?account='+encodeURIComponent(preferred):''));csrf=state.csrf;accountId=state.selected_account_id||state.accounts[0]?.account_id||'';
    const desired=new URL(location.href).searchParams.get('site');
    if(!account()?.sites.some(s=>s.site_id===siteId))siteId=account()?.sites.find(s=>s.site_id===desired)?.site_id||account()?.sites[0]?.site_id||'';
    $('login').hidden=true;$('shell').hidden=false;
  }
  function view(){return location.hash.slice(1).split('/')[0]||(isSpecialist()?'work':'overview');}
  function nav(){
    const current=view(),clientNav=[['overview','Обзор','overview'],['diagnostics','Проверка сайта','diagnostics'],['requests','Обращения','requests'],...(Number(site()?.form_required)?[['leads','Заявки','leads']]:[]),['reviews','Отзывы','reviews'],['settings','Настройки','settings']];
    const specialistNav=[['work','Рабочая очередь','requests'],['clients','Клиенты','clients'],['diagnostics','Проверка сайта','diagnostics'],['connections','Подключения','link'],['reviews','Отзывы','reviews'],['billing','Сопровождение','billing'],['settings','Настройки','settings']];
    $('navigation').setAttribute('aria-label',isSpecialist()?'Навигация поддержки':'Навигация клиента');
    $('navigation').innerHTML=(isSpecialist()?specialistNav:clientNav).map(([id,label,symbol])=>`<a href="#${id}" title="${label}" ${current===id?'aria-current="page"':''}>${icon(symbol)}<span class="nav-label">${label}</span></a>`).join('');
    document.querySelector('.sidebar .brand').href=isSpecialist()?'#work':'#overview';
    $('navCaption').textContent=isSpecialist()?'Сопровождение клиентов':'Ваш сайт';
    $('profileName').textContent=state.user.display_name;$('profileRole').textContent=isSpecialist()?'Специалист':account()?.name||'Клиент';
    $('avatar').textContent=(state.user.display_name||'SC').slice(0,1).toUpperCase();
    $('projectName').textContent=site()?.name||account()?.name||'SiteCare';$('projectDomain').textContent=site()?.target_origin?.replace(/^https?:\/\//,'')||'Кабинет сопровождения';
    const all=state.accounts.flatMap(a=>a.sites.map(s=>({s,a})));
    $('siteSelect').innerHTML=all.map(({s,a})=>`<option value="${h(s.site_id)}" ${s.site_id===siteId?'selected':''}>${h(isSpecialist()?a.name+' · '+s.name:s.name)}</option>`).join('');$('siteSelectWrap').hidden=all.length<=1;
    $('siteOpen').hidden=!site();$('siteOpen').href=safeUrl(site()?.target_url||site()?.target_origin)||'#';
  }
  function findRows(items,limit=items.length){return items.slice(0,limit).map((f,i)=>`<article class="item"><span class="item-number">${String(i+1).padStart(2,'0')}</span><div class="item-main"><button class="item-title" data-action="finding" data-id="${h(f.id)}">${h(f.title)}</button><p>${h(f.impact)}</p><div class="item-meta">${badge(f.kind)}<span class="small muted">${h(categoryNames[f.category]||'Проверка')} · ${h(new URL(f.page).pathname)}</span></div></div><button class="icon-button" aria-label="Открыть: ${h(f.title)}" data-action="finding" data-id="${h(f.id)}">${icon('arrow')}</button></article>`).join('');}
  function requestRows(rows){return rows.map(r=>`<article class="item"><div class="item-main"><button class="item-title" data-action="request" data-id="${h(r.request_id)}" data-site="${h(r.site_id)}">${h(r.title)}</button><div class="item-meta">${badge(r.status)}${r.quote_minor!=null?`<span class="small">${r.quote_minor===0?'Входит в сопровождение':money(r.quote_minor)}</span>`:''}<span class="small muted">${h(date(r.updated_at))}</span>${r.account_name?`<span class="small muted">${h(r.account_name)}</span>`:''}</div></div><button class="icon-button" aria-label="Открыть обращение" data-action="request" data-id="${h(r.request_id)}" data-site="${h(r.site_id)}">${icon('arrow')}</button></article>`).join('');}
  function overview(){
    const s=site(),findings=care.findings,open=care.requests.filter(r=>!closed(r)),problems=findings.filter(f=>f.kind==='problem');
    const fresh=s.last_monitor_at&&Date.now()-Date.parse(s.last_monitor_at)<Math.max(30,Number(s.monitor_interval_minutes||5)*3)*60000;
    const headline=!fresh?'Нужна свежая проверка':problems.length?'Есть проблема с доступностью':Number(s.page_ok)===1?'Сайт ответил на последнюю проверку':'Ответ сайта требует проверки';
    const description=!fresh?'Пока недостаточно актуальных данных, чтобы оценить состояние сайта. Запустите проверку.':Number(s.page_ok)===1?'Это подтверждает доступность из точки проверки SiteCare. Замечания по содержимому и задачи специалисту — ниже.':'SiteCare зафиксировал ошибку запроса. Откройте подробности и передайте результат специалисту.';
    return pageHead('Обзор сайта','Состояние, замечания и работа по вашему сайту.',!isSpecialist()&&canManage()?button('Создать обращение','new-request'):'' )+
      `<section class="status-banner ${problems.length?'problem':''}"><div class="status-symbol">${icon(problems.length?'alert':fresh&&Number(s.page_ok)===1?'check':'clock')}</div><div><h2>${h(headline)}</h2><p>${h(description)}</p><p class="small space-1">Последняя проверка: ${h(date(s.last_monitor_at))}</p></div></section>`+
      `<div class="metrics">${metric('Доступность по проверкам',report.uptimePercent==null?'Нет данных':report.uptimePercent+'%',report.checks+' проверок за '+report.days+' дней')}${metric('Время ответа',report.averageLatencyMs==null?'Нет данных':report.averageLatencyMs+' мс','Средний ответ сервера, не полная загрузка')}${metric('Задачи специалисту',open.length,'Открытые обращения по этому сайту')}</div>`+
      `<div class="columns"><section class="panel"><div class="panel-head"><h2>На что обратить внимание</h2>${link('Все замечания','diagnostics')}</div>${findings.length?findRows(findings,4):empty('Подтверждённых замечаний пока нет',care.checkedAt?'В пределах выполненной проверки. Это не гарантирует отсутствие других проблем.':'Запустите первую проверку — здесь появятся её результаты.')}</section><div class="stack"><section class="panel"><div class="panel-head"><h2>В работе</h2><a href="#requests">Все</a></div>${open.length?requestRows(open.slice(0,3)):empty('Открытых задач нет','Опишите нужную правку или задайте вопрос специалисту.',canManage()?button('Написать','new-request','',true):'')}</section><section class="panel"><h2>Как проходит сопровождение</h2><p class="muted small space-2">Вы описываете задачу. Специалист согласует объём, срок и стоимость, вносит изменения в Tilda и сообщает результат проверки.</p><a href="#requests">Поддержка сайта ${icon('arrow')}</a></section></div></div>`;
  }
  function diagnostics(){
    const items=care.findings.filter(f=>(filter==='all'||f.kind===filter)&&(!search||(f.title+' '+f.page).toLowerCase().includes(search.toLowerCase())));
    return pageHead('Проверка сайта','Факты из опубликованных страниц. Причины и влияние указаны отдельно.',canManage()&&enabled('control')?button('Обновить проверку','scan'):'' )+
      `<div class="toolbar"><div class="filters">${[['all','Все'],['problem','Сбои'],['review','Проверить'],['improvement','Улучшить'],['outdated','Устаревшие']].map(([v,l])=>`<button class="filter" data-action="filter" data-value="${v}" aria-pressed="${filter===v}">${l}</button>`).join('')}</div><input class="search" type="search" id="findingSearch" aria-label="Поиск по замечаниям и страницам" placeholder="Найти страницу или замечание" value="${h(search)}"></div>`+
      `<section class="panel"><div class="panel-head"><h2>${items.length} замечаний</h2><span class="small muted">${h(date(care.checkedAt))}</span></div>${items.length?findRows(items):empty('В этом списке нет замечаний',care.checkedAt?'Другие типы результатов доступны через фильтры.':'Данные появятся после первой полной проверки.')}</section><div class="notice space-3"><b>Границы проверки</b><br>Проверено страниц: ${h(care.coverage.pages)}${care.coverage.failedPages?`; не удалось получить: ${h(care.coverage.failedPages)}`:''}${care.coverage.truncated?'; список страниц ограничен':''}. ${h(care.coverage.limitations)} Причины — гипотезы до проверки специалистом. Рекомендация не означает поломку или потерю заявок.</div>`;
  }
  function requestsPage(){
    if(selectedRequest&&detail)return requestDetail();
    const rows=care.requests.filter(r=>filter==='closed'?closed(r):filter==='all'?true:!closed(r));
    return pageHead('Поддержка сайта','Все договорённости и результаты сохраняются в обращениях.',canManage()?button('Новое обращение','new-request'):'' )+
      `<div class="toolbar"><div class="filters">${[['all','Все обращения'],['open','Открытые'],['closed','Завершённые']].map(([v,l])=>`<button class="filter" data-action="filter" data-value="${v}" aria-pressed="${filter===v}">${l}</button>`).join('')}</div></div><section class="panel">${rows.length?requestRows(rows):empty('Здесь будут ваши обращения','Можно попросить заменить номер, исправить страницу или уточнить результат диагностики.',canManage()?button('Создать первое обращение','new-request'):'' )}</section>`;
  }
  function requestDetail(){
    const r=detail.request,specialist=isSpecialist();let evidence={};try{evidence=JSON.parse(r.evidence_json);}catch{}
    const steps=['new','quoted','approved','in_progress','completed'];
    let actionMarkup='';
    if(!closed(r)&&canManage()){
      if(specialist&&r.status==='new')actionMarkup+=button('Закрыть с ответом','answer','',true);
      if(specialist&&['new','quoted'].includes(r.status))actionMarkup+=button(r.status==='quoted'?'Уточнить предложение':'Подготовить предложение','quote','',true);
      if(!specialist&&r.status==='quoted')actionMarkup+=button('Согласовать предложение','accept');
      if(specialist&&r.status==='approved'&&r.quote_minor>0&&!r.paid_at)actionMarkup+=button('Подтвердить полученную оплату','payment','',true);
      if(specialist&&r.status==='approved'&&(r.quote_minor===0||r.paid_at))actionMarkup+=button('Начать работу','care-start');
      if(specialist&&['in_progress','waiting_client'].includes(r.status))actionMarkup+=button('Завершить с результатом','complete');
      if(!r.paid_at&&['new','quoted','approved'].includes(r.status))actionMarkup+=button('Отменить задачу','cancel','',true);
    }
    return pageHead(r.title,`Создано ${date(r.created_at)}`,button('К списку',isSpecialist()?'back-work':'back-requests','',true))+
      `<div class="row">${badge(r.status)}<span class="small muted">${h(site().name)}</span></div><div class="progress-steps">${steps.map((s,i)=>`<span class="${(r.status==='waiting_client'?'in_progress':r.status)===s?'current':''}">${i+1}. ${statusNames[s]}</span>`).join('')}</div>`+
      `<div class="columns"><section class="panel"><div class="panel-head"><h2>Переписка</h2>${button('Обновить','refresh-request','',true)}</div><div class="messages">${detail.messages.map(m=>`<article class="message ${h(m.role)}"><div class="avatar">${m.role==='support'?'SC':'В'}</div><div class="bubble"><div class="message-meta"><b>${m.role==='support'?'Специалист':m.role==='ai'?'История помощника':'Клиент'}</b><time>${h(date(m.createdAt))}</time></div><p>${h(m.content)}</p></div></article>`).join('')||empty('История пока пуста','Новое сообщение появится здесь.')}</div>${!closed(r)&&canManage()?`<form class="composer" data-form="message">${field('content',specialist?'Сообщение клиенту':'Сообщение специалисту','', 'textarea')}<div class="actions"><button class="button">Отправить сообщение</button>${specialist&&r.status==='in_progress'?button('Запросить уточнение','wait','',true):''}</div></form>`:''}</section><aside class="stack">${r.quote_minor!=null?`<section class="quote"><h2>Предложение по задаче</h2><p class="price">${r.quote_minor===0?'В сопровождении':money(r.quote_minor)}</p><p>${h(r.quote_scope)}</p><p class="small"><b>Срок:</b> ${h(r.quote_due)}</p>${r.accepted_at?`<p class="small">Согласовано клиентом: ${h(date(r.accepted_at))}</p>`:''}${r.quote_minor>0?`<p class="small">${r.paid_at?'Получение оплаты подтверждено специалистом '+h(date(r.paid_at)):'Оплата не подтверждена. Согласуйте способ оплаты в переписке.'}</p>`:'<p class="small">Дополнительная оплата не требуется.</p>'}<div class="actions">${actionMarkup}</div></section>`:`<section class="panel"><h2>Сначала согласуем задачу</h2><p class="muted small space-2">Специалист предложит объём, цену и срок. До вашего согласия платная работа не начинается.</p><div class="actions">${actionMarkup}</div></section>`}${r.resolution?`<section class="panel"><h2>Итог обращения</h2><p class="review-text">${h(r.resolution)}</p><h3>Как проверено</h3><p class="review-text">${h(r.verification)}</p>${button('Повторить диагностику','scan','',true)}<p class="muted small space-1">Завершение обращения само по себе не подтверждает исправление автоматической проверкой.</p></section>`:''}${evidence.id?`<section class="panel"><h2>Основание обращения</h2><p class="review-text">${h(evidence.evidence)}</p><p class="small">${external(evidence.page,'Страница с замечанием')}</p><p class="muted small space-4">Снимок проверки: ${h(date(evidence.checkedAt))}</p></section>`:''}</aside></div>`;
  }
  async function leadsPage(){
    if(!Number(site().form_required))return pageHead('Заявки','Приём форм не используется для этого сайта.')+empty('Формы не подключены','Если нужно принимать заявки в кабинете, напишите специалисту.',button('Обсудить подключение','new-request'));
    const token=renderId;
    if(!leadRows.length){const d=await api('/v1/platform/accounts/'+accountId+'/leads?site='+encodeURIComponent(siteId));if(token!==renderId)return '';leadRows=d.leads||[];leadMore=Boolean(d.hasMore);leadCursor=d.cursor||null;}
    const statuses={new:'Новая',in_progress:'В работе',completed:'Обработана',spam:'Спам'};
    return pageHead('Заявки с сайта','Контакты и сообщения посетителей. Статус отмечаете вы.',button('Обновить список','refresh-leads','',true))+
      `<section class="panel">${leadRows.length?leadRows.filter(l=>l.siteId===siteId).map(l=>`<article class="item"><div class="avatar">${h((l.name||'Г')[0])}</div><div class="item-main"><h3>${h(l.name||'Посетитель сайта')}</h3><div class="item-meta"><span class="small muted">${h(date(l.receivedAt))} · ${h(l.formLabel||'Форма сайта')}</span>${badge(l.status,statuses[l.status])}</div><p>${h(l.phone||'')} ${h(l.email||'')}</p><p class="review-text">${h(l.message||'Сообщение не заполнено')}</p>${l.note?`<div class="notice">${h(l.note)}</div>`:''}<div class="actions space-5">${button('Открыть заявку','lead',`data-id="${h(l.leadId)}"`,true)}</div></div></article>`).join(''):empty('Заявок пока нет','Отсутствие заявок не означает, что форма сломана. Специалист может выполнить тестовую отправку.')}${leadMore?`<div class="actions space-3">${button('Загрузить ещё','more-leads','',true)}</div>`:''}</section>`;
  }
  async function reviewsPage(){
    const token=renderId,data=await api(siteApi('/review-widgets'));if(token!==renderId)return '';reviews=data;
    return pageHead('Отзывы клиентов','Источники и последние полученные отзывы.',isSpecialist()?button('Подключить источник','add-review'):canManage()?button('Обсудить отзывы','new-request','',true):'')+
      (!enabled('reviews')&&!isSpecialist()?`<div class="notice space-6">Модуль отзывов не подключён. Возможность и стоимость подключения можно обсудить со специалистом.</div>`:'')+
      (reviews.widgets.length?`<div class="two">${reviews.widgets.map(w=>`<section class="panel"><div class="review-source"><div class="source-mark">${h(w.serviceLabel.slice(0,1))}</div><div class="item-main"><h2>${h(w.serviceLabel)}</h2><span class="small muted">${w.reviewCount} отзывов ${w.averageRating!=null?'· '+w.averageRating+' / 5':''}</span></div>${badge(!w.enabled?'canceled':w.syncStatus==='ok'?'ok':w.syncStatus==='failed'?'review':'new',!w.enabled?'Скрыт':w.syncStatus==='ok'?'Обновлён':w.syncStatus==='failed'?'Обновление задержалось':'Ожидаем загрузку')}</div>${w.lastSyncError?`<div class="notice">${h(w.lastSyncError)} ${w.lastSuccessAt?'Показываем последнюю успешную загрузку.':''}</div>`:''}<div class="small muted space-7">Последняя загрузка: ${h(date(w.lastSuccessAt))}</div>${w.previewReviews.length?w.previewReviews.map(r=>`<article class="item"><div class="item-main"><h3>${h(r.authorName)}</h3><div class="stars">${r.rating?'★'.repeat(Math.round(Math.min(5,Math.max(0,r.rating)))):''}</div><p class="review-text">${h(r.text)}</p></div></article>`).join(''):empty(w.renderMode==='iframe'?'Отзывы показывает источник':'Отзывов ещё нет',w.renderMode==='iframe'?'Источник предоставляет собственный встроенный блок.':'SiteCare ожидает первую успешную загрузку.')}<div class="actions space-8">${external(w.businessIdentifier,'Открыть источник')}${isSpecialist()?button('Настроить','edit-review',`data-id="${h(w.widgetId)}"`,true):''}</div></section>`).join('')}</div>`:empty('Источники ещё не подключены','Специалист подключит карточку именно вашей организации.'));
  }
  async function workPage(){
    if(selectedRequest&&detail)return requestDetail();queue=(await api('/v1/platform/care/queue')).requests;
    const rows=queue.filter(r=>filter==='closed'?closed(r):!closed(r));
    return pageHead('Рабочая очередь','Согласования, работа и ответы клиентам.',button('Обновить','refresh','',true))+
      `<div class="metrics">${metric('Ждут предложения',queue.filter(r=>r.status==='new').length,'Новые обращения')}${metric('Согласование и оплата',queue.filter(r=>['quoted','approved'].includes(r.status)).length,'Работа ещё не начата')}${metric('В работе',queue.filter(r=>['in_progress','waiting_client'].includes(r.status)).length,'Активные задачи')}</div><div class="toolbar"><div class="filters">${[['all','Открытые'],['closed','Архив']].map(([v,l])=>`<button class="filter" data-action="filter" data-value="${v}" aria-pressed="${filter===v}">${l}</button>`).join('')}</div></div><section class="panel">${rows.length?requestRows(rows):empty('В очереди пока нет задач','Новые обращения клиентов появятся здесь.')}</section>`;
  }
  function clientsPage(){return pageHead('Клиенты','Сайты, доступы и условия сопровождения.',button('Добавить клиента','add-client'))+`<section class="panel"><div class="table-scroll"><table class="table"><thead><tr><th>Клиент</th><th>Сайты</th><th>Сопровождение</th><th>Действия</th></tr></thead><tbody>${state.accounts.map(a=>`<tr><td><b>${h(a.name)}</b><small>${h(a.owner?.email||'Доступ ещё не активирован')}</small></td><td>${a.sites.map(s=>`<button class="quiet" data-action="select-site" data-id="${h(s.site_id)}">${h(s.name)}</button>`).join('')||'Нет сайтов'}</td><td>${h(a.features.control.label)}</td><td>${button('Управление','client',`data-id="${h(a.account_id)}"`,true)}</td></tr>`).join('')}</tbody></table></div>${!state.accounts.length?empty('Подключите первого клиента','Приглашение позволит клиенту самостоятельно установить пароль.') :''}</section>`;}
  async function connectionsPage(){
    const data=await api(siteApi('/integration'));const s=site();
    return pageHead('Подключение сайта','Технические настройки доступны только специалисту.',button('Проверить подключение','check-connection'))+
      `<div class="two"><section class="panel"><h2>Публикация и формы</h2><dl class="detail-grid"><dt>Страница</dt><dd>${external(s.target_url||s.target_origin,'Открыть сайт')}</dd><dt>Код SiteCare</dt><dd>${badge(s.loader_ok===1?'ok':'review',s.loader_ok===1?'Обнаружен':'Не подтверждён')}</dd><dt>Тест формы</dt><dd>${s.form_verified_at?h(date(s.form_verified_at)):'Не подтверждён'}</dd></dl><div class="actions">${button('Настроить сайт','site-settings','',true)}${Number(s.form_required)?button('Новый адрес приёмщика','webhook','',true):''}${Number(s.form_required)?button('Создать тест формы','form-test','',true):''}</div></section><section class="panel"><h2>Уведомления</h2><div class="settings-row"><div><h3>Telegram</h3><p>${s.telegram_enabled?'Подключён':'Не подключён'}</p></div>${button('Настроить','telegram','',true)}</div><div class="settings-row"><div><h3>Яндекс Метрика</h3><p>${s.yandex_metrica_connected_at?'Подключена':'Не подключена'}</p></div>${button(s.yandex_metrica_connected_at?'Отключить':'Подключить',s.yandex_metrica_connected_at?'metrica-disconnect':'metrica-connect','',true)}</div></section></div><section class="panel space-3"><h2>Код подключения</h2><p class="muted small space-2">Сохраните существующий код в HEAD. Добавьте SiteCare с новой строки и перепубликуйте страницы. Код больше не изменяет содержимое сайта.</p><code class="code">${h(data.loaderCode||data.urls?.loaderCode||data.integration?.loaderCode||'')}</code>${(data.webhookUrl||data.urls?.webhookUrl)?`<h3 class="space-9">Приёмщик форм</h3><code class="code">${h(data.webhookUrl||data.urls?.webhookUrl)}</code>`:''}${data.reviewsWidgetCode?`<h3 class="space-9">Блок отзывов</h3><code class="code">${h(data.reviewsWidgetCode)}</code>`:''}</section>`;
  }
  function billingPage(){return pageHead('Условия сопровождения','Доступ к сервису и отдельные задачи учитываются раздельно.',button('Тарифы','products','',true))+`<section class="panel"><div class="table-scroll"><table class="table"><thead><tr><th>Клиент</th><th>Сопровождение</th><th>Отзывы</th><th>Действует до</th><th></th></tr></thead><tbody>${state.accounts.map(a=>`<tr><td>${h(a.name)}</td><td>${h(a.features.control.label)}</td><td>${h(a.features.reviews.label)}</td><td>${h(date(a.billing.currentPeriodEnd))}</td><td>${button('Изменить условия','billing',`data-id="${h(a.account_id)}"`,true)}</td></tr>`).join('')}</tbody></table></div></section><div class="notice space-3">Стоимость отдельных правок согласуется в обращении. Изменение доступа к сервису не подтверждает получение оплаты по задаче.</div>`;}
  function settingsPage(){
    const a=account(),s=site();return pageHead('Настройки','Профиль, доступ к кабинету и условия сопровождения.')+
      `<div class="two"><section class="panel"><h2>Профиль и доступ</h2>${isSpecialist()?`<div class="settings-row"><div><h3>Обращения клиентов</h3><p>Уведомления специалисту в Telegram</p></div>${button('Настроить','support-telegram','',true)}</div>`:''}<div class="settings-row"><div><h3>${h(state.user.display_name)}</h3><p>${h(state.user.email)}</p></div>${button('Изменить пароль','password','',true)}</div>${a?`<div class="settings-row"><div><h3>Участники кабинета</h3><p>${a.members.length} участников</p></div>${button('Управление','members','',true)}</div>`:''}<div class="settings-row"><div><h3>Уведомления в Telegram</h3><p>${s?.telegram_enabled?'Уведомления сайта подключены':'Уведомления сайта не подключены'}</p></div>${s?button('Настроить','telegram','',true):''}</div></section><section class="panel"><h2>Сопровождение</h2>${a?`<div class="settings-row"><div><h3>Контроль сайта</h3><p>${h(a.features.control.label)}</p></div>${badge(a.features.control.enabled?'ok':'outdated',a.features.control.enabled?'Доступен':'Нет доступа')}</div><div class="settings-row"><div><h3>Отзывы</h3><p>${h(a.features.reviews.label)}</p></div>${badge(a.features.reviews.enabled?'ok':'outdated',a.features.reviews.enabled?'Доступны':'Не подключены')}</div><p class="muted small space-8">Правки оцениваются отдельно или включаются в сопровождение. Объём и стоимость фиксируются до начала работы.</p>${a.billing.checkoutUrl?`<div class="actions space-8">${external(a.billing.checkoutUrl,'Оплатить сопровождение')}</div>`:''}`:empty('Кабинет пока не подключён','Обратитесь к специалисту, выдавшему приглашение.')}</section></div>${a?`<section class="panel space-3"><div class="panel-head"><h2>Сайты кабинета</h2>${isSpecialist()?button('Добавить сайт','add-site','',true):''}</div>${a.sites.map(s=>`<div class="settings-row"><div><h3>${h(s.name)}</h3><p>${h(s.target_origin)}</p></div>${button('Открыть','select-site',`data-id="${h(s.site_id)}"`,true)}</div>`).join('')}</section>`:''}`;
  }
  async function render(){
    if(!state)return;const token=++renderId;nav();$('view').innerHTML='<div class="loading" role="status">Загружаем данные…</div>';
    try{
      let markup;const v=view();
      if(isSpecialist()&&['work','clients','billing'].includes(v))markup=v==='work'?await workPage():v==='clients'?clientsPage():billingPage();
      else if(v==='settings')markup=settingsPage();
      else if(!site())markup=pageHead('Сайт ещё не подключён','Специалист завершит настройку кабинета.')+empty('Подключение в процессе','После подключения здесь появятся состояние сайта и обращения.');
      else {
        if(!care){const data=await api(siteApi('/care'));if(token!==renderId)return;care=data;}
        if(v==='overview'){if(!report){const data=await api(siteApi('/report?days=30'));if(token!==renderId)return;report=data;}markup=overview();}
        else if(v==='diagnostics')markup=diagnostics();
        else if(v==='requests')markup=requestsPage();
        else if(v==='reviews')markup=await reviewsPage();
        else if(v==='leads')markup=await leadsPage();
        else if(v==='connections'&&isSpecialist())markup=await connectionsPage();
        else markup=pageHead('Раздел недоступен','Выберите доступный раздел в меню.');
      }
      if(token!==renderId)return;$('view').innerHTML=markup;document.title=(document.querySelector('#view h1')?.textContent||'Кабинет')+' · SiteCare';
    }catch(error){if(token!==renderId)return;$('view').innerHTML=`<div class="notice error" role="alert">${h(error.message)}</div><div class="actions space-3">${button('Повторить','refresh','',true)}</div>`;}
  }
  function modal(title,markup){dialogReturnFocus=document.activeElement;$('dialogTitle').textContent=title;$('dialogContent').innerHTML=markup;$('dialog').showModal();}
  function formModal(title,type,markup,submit='Сохранить'){modal(title,`<form data-form="${h(type)}">${markup}<div class="notice error" id="formError" hidden></div><div class="actions"><button class="button">${h(submit)}</button>${button('Отмена','close','',true)}</div></form>`);}
  async function switchSite(id){++renderId;const a=state.accounts.find(a=>a.sites.some(s=>s.site_id===id));if(!a)return;siteId=id;accountId=a.account_id;care=report=detail=null;selectedRequest='';leadRows=[];leadCursor=null;await loadDashboard(accountId);}
  async function openRequest(id,sid=siteId){if(sid!==siteId)await switchSite(sid);selectedRequest=id;const expectedSite=siteId,data=await api(siteApi('/care/'+encodeURIComponent(id)));if(expectedSite!==siteId||selectedRequest!==id)return;detail=data;if(!['work','requests'].includes(view()))location.hash=isSpecialist()?'work':'requests';else await render();}
  async function actCare(action,body={}){detail=await api(siteApi('/care/'+detail.request.request_id),'POST',{action,revision:detail.request.revision,...body});care=null;await render();}
  function findingDialog(id){const f=care.findings.find(f=>f.id===id);if(!f)return;modal(f.title,`${badge(f.kind)}<dl class="detail-grid"><dt>Где</dt><dd>${external(f.page,f.page)}</dd><dt>Что обнаружено</dt><dd>${h(f.evidence)}</dd><dt>Проверено</dt><dd>${h(date(f.checkedAt))} · ${h(f.source)}</dd><dt>Возможная причина</dt><dd>${h(f.cause)}<br><span class="small muted">Гипотеза — требует проверки специалистом.</span></dd><dt>На что влияет</dt><dd>${h(f.impact)}</dd><dt>Что сделать</dt><dd>${h(f.action)}</dd></dl><div class="actions">${!isSpecialist()&&canManage()?button('Передать специалисту','new-request',`data-finding="${h(f.id)}"`):''}${button('Закрыть','close','',true)}</div>`);}
  async function action(name,el){
    if(name==='close'){$('dialog').close();return;}
    if(name==='refresh'){care=report=null;await loadDashboard();await render();return;}
    if(name==='filter'){filter=el.dataset.value;await render();return;}
    if(name==='finding'){findingDialog(el.dataset.id);return;}
    if(name==='select-site'){$('dialog').close();await switchSite(el.dataset.id);location.hash=isSpecialist()?'diagnostics':'overview';await render();return;}
    if(name==='request'){await openRequest(el.dataset.id,el.dataset.site);return;}
    if(name==='refresh-request'){await openRequest(selectedRequest);return;}
    if(name==='back-requests'||name==='back-work'){selectedRequest='';detail=null;care=null;await render();return;}
    if(name==='new-request'){
      const f=care?.findings.find(f=>f.id===el.dataset.finding);$('dialog').close();
      formModal('Новое обращение','new-request',field('title','Что нужно сделать',f?.title||'')+field('content','Описание задачи',f?'Пожалуйста, проверьте это замечание и предложите решение.':'','textarea','Например: заменить номер +7 … на +7 … на всех страницах. Укажите адрес страницы и желаемый результат.')+`<input type="hidden" name="findingId" value="${h(f?.id||'')}"><div class="notice">Создание обращения не запускает платную работу. Сначала специалист согласует с вами объём, стоимость и срок.</div>`,'Отправить специалисту');return;
    }
    if(name==='scan'){toast('Проверяем опубликованные страницы. Это может занять около минуты.');await api(siteApi('/care/check'),'POST',{});care=report=null;await loadDashboard();await render();toast('Результаты проверки обновлены.');return;}
    if(name==='answer'){formModal('Ответ без выполнения работ','answer','<p>Подходит для консультации. Если нужны изменения сайта, подготовьте предложение по задаче.</p>'+field('resolution','Ответ клиенту','','textarea'),'Отправить ответ и закрыть');return;}
    if(name==='quote'){formModal('Предложение по задаче','quote',field('scope','Что входит в работу',detail.request.quote_scope||'','textarea')+field('amount','Стоимость, ₽',detail.request.quote_minor==null?'':String(detail.request.quote_minor/100),'text','0 — работа включена в сопровождение. Стоимость фиксируется до согласия клиента.')+field('due','Срок',detail.request.quote_due||'','text','Например: 2 рабочих дня после подтверждения оплаты.'),'Отправить на согласование');return;}
    if(name==='accept'){formModal('Согласовать предложение','accept',`<div class="quote"><p>${h(detail.request.quote_scope)}</p><b>${detail.request.quote_minor===0?'Входит в сопровождение':money(detail.request.quote_minor)}</b><p>Срок: ${h(detail.request.quote_due)}</p></div><p class="muted small space-8">Вы соглашаетесь с указанным объёмом, ценой и сроком. Это действие не списывает деньги.</p>`,'Согласовать');return;}
    if(name==='payment'){formModal('Подтверждение полученной оплаты','payment',`<div class="notice">Отметьте только фактически полученные ${money(detail.request.quote_minor)}. Это ручная запись специалиста, не проверка платёжного сервиса.</div>`+field('reference','Основание платежа','','text','Дата и номер платежа или счёта. Не вводите данные банковской карты.'),'Подтвердить получение');return;}
    if(name==='care-start'){await actCare('start');return;}
    if(name==='wait'){const value=$('view').querySelector('[name=content]')?.value||'';await actCare('wait',{content:value});return;}
    if(name==='complete'){formModal('Завершить задачу','complete',field('resolution','Что изменено','','textarea')+field('verification','Как проверено','','textarea','Укажите страницу, выполненную проверку и её результат. Это заключение специалиста, а не автоматическое подтверждение.'),'Сохранить результат');return;}
    if(name==='cancel'){formModal('Отменить задачу','cancel','<p>Задача будет закрыта. История переписки сохранится.</p>','Отменить задачу');return;}
    if(name==='password'){formModal('Изменить пароль','password',field('currentPassword','Текущий пароль','','password')+field('newPassword','Новый пароль','','password'));return;}
    if(name==='refresh-leads'){leadRows=[];await render();return;}
    if(name==='more-leads'){const params=new URLSearchParams({site:siteId});if(leadCursor?.receivedAt)params.set('before',leadCursor.receivedAt);if(leadCursor?.leadId)params.set('beforeId',leadCursor.leadId);const expectedSite=siteId,d=await api('/v1/platform/accounts/'+accountId+'/leads?'+params);if(expectedSite!==siteId)return;leadRows.push(...(d.leads||[]));leadCursor=d.cursor;leadMore=Boolean(d.hasMore);await render();return;}
    if(name==='lead'){const l=leadRows.find(l=>l.leadId===el.dataset.id);if(!l)return;formModal('Заявка посетителя','lead',`<input type="hidden" name="leadId" value="${h(l.leadId)}"><p class="review-text">${h(l.name)}<br>${h(l.phone)}<br>${h(l.email)}<br>${h(l.message)}</p>${(l.fields||[]).map(f=>`<p class="small"><b>${h(f.name)}:</b> ${h(f.value)}</p>`).join('')}`+selectField('status','Статус',[['new','Новая'],['in_progress','В работе'],['completed','Обработана'],['spam','Спам']],l.status)+field('note','Заметка',l.note||'','textarea'));$('f-note').required=false;return;}
    if(name==='add-client'){formModal('Новый клиент','add-client',field('name','Название кабинета')+field('ownerName','Имя клиента')+field('ownerEmail','Email клиента','','email'),'Создать приглашение');return;}
    if(name==='client'){await loadDashboard(el.dataset.id);modal(account().name,`<div class="actions">${button('Доступы','members','',true)}${button('Добавить сайт','add-site','',true)}${button('Условия сопровождения','billing',`data-id="${h(accountId)}"`,true)}</div><div class="space-10">${account().sites.map(s=>`<div class="settings-row"><b>${h(s.name)}</b>${button('Открыть сайт в кабинете','select-site',`data-id="${h(s.site_id)}"`,true)}</div>`).join('')}</div>`);return;}
    if(name==='members'){ $('dialog').close();const a=account();modal('Участники кабинета',`${a.members.map(m=>`<div class="settings-row"><div><b>${h(m.display_name)}</b><p class="small muted">${h(m.email)} · ${h({owner:'Владелец',admin:'Администратор',manager:'Менеджер',viewer:'Наблюдатель'}[m.role])}</p></div><div class="actions">${(isSpecialist()||a.role==='owner')&&m.role!=='owner'?button('Изменить роль','member-role',`data-id="${h(m.user_id)}"`,true):''}${isSpecialist()?button('Управление доступом','member-access',`data-id="${h(m.user_id)}"`,true):''}</div></div>`).join('')}${isSpecialist()||['owner','admin'].includes(a.role)?`<div class="actions space-10">${button('Пригласить участника','invite','',true)}</div>`:''}`);return;}
    if(name==='member-role'){const m=account().members.find(m=>m.user_id===el.dataset.id);$('dialog').close();formModal('Роль участника','member-role',`<input type="hidden" name="userId" value="${h(m.user_id)}">`+selectField('role','Роль',[['admin','Администратор'],['manager','Менеджер'],['viewer','Наблюдатель']],m.role));return;}
    if(name==='member-access'){const m=account().members.find(m=>m.user_id===el.dataset.id);$('dialog').close();modal('Доступ: '+m.display_name,`<p>${h(m.email)} · ${m.status==='active'?'Активен':'Приостановлен'}</p><div class="actions">${button('Восстановить пароль','access-link',`data-id="${h(m.user_id)}"`,true)}${button('Завершить сеансы','close-sessions',`data-id="${h(m.user_id)}"`,true)}${button(m.status==='active'?'Приостановить доступ':'Возобновить доступ','member-status',`data-id="${h(m.user_id)}" data-status="${m.status==='active'?'suspended':'active'}"`,true)}</div>`);return;}
    if(name==='close-sessions'||name==='member-status'){$('dialog').close();formModal(name==='close-sessions'?'Завершить сеансы':el.dataset.status==='active'?'Возобновить доступ':'Приостановить доступ',name,`<input type="hidden" name="userId" value="${h(el.dataset.id)}"><input type="hidden" name="status" value="${h(el.dataset.status||'')}"><p>Изменение применяется к учётной записи участника во всех его кабинетах.</p>`,'Подтвердить');return;}
    if(name==='invite'){$('dialog').close();formModal('Пригласить участника','invite',field('email','Email','','email')+selectField('role','Роль',[['manager','Менеджер — обращения и заявки'],['viewer','Наблюдатель — только просмотр'],['admin','Администратор кабинета']],'manager'),'Создать ссылку');return;}
    if(name==='access-link'){const d=await api('/v1/platform/operator/accounts/'+accountId+'/users/'+el.dataset.id+'/access-link','POST',{});modal('Восстановление доступа',`<p>Одноразовая ссылка для клиента:</p><code class="code">${h(d.resetUrl||d.accessUrl||d.inviteUrl||d.url||'')}</code>`);return;}
    if(name==='add-site'){$('dialog').close();formModal('Подключить сайт','add-site',field('name','Название сайта')+field('targetUrl','Адрес сайта','','url')+selectField('formRequired','Приём заявок',[['1','Есть формы'],['0','Формы не используются']],'1'));return;}
    if(name==='site-settings'){formModal('Настройки сайта','site-settings',field('name','Название',site().name)+selectField('formRequired','Приём форм',[['1','Используется'],['0','Не используется']],String(site().form_required)));return;}
    if(name==='check-connection'){await api(siteApi('/check'),'POST',{});await loadDashboard();await render();return;}
    if(name==='webhook'){formModal('Новый адрес приёмщика форм','webhook','<p>Текущий адрес перестанет принимать формы. Сразу замените его в настройках Tilda, перепубликуйте сайт и выполните тестовую отправку. Новый адрес будет показан один раз.</p><label class="check"><input type="checkbox" required> Я понимаю, что старый адрес перестанет работать</label>','Создать адрес');return;}
    if(name==='form-test'){const d=await api(siteApi('/forms/test'),'POST',{});modal('Тестовая отправка',`<p>Используйте этот маркер при отправке формы на сайте. После отправки повторите проверку подключения.</p><code class="code">${h(d.marker||d.testMarker||'')}</code>`);return;}
    if(name==='products'){modal('Тарифы сопровождения',state.products.map(p=>`<div class="settings-row"><div><h3>${h(p.name)}</h3><p>${h(p.description)}</p><b>${h(new Intl.NumberFormat('ru-RU',{style:'currency',currency:p.currency}).format(p.priceMinor/100))}</b></div>${button('Настроить','product',`data-id="${h(p.productKey)}"`,true)}</div>`).join(''));return;}
    if(name==='product'){const p=state.products.find(p=>p.productKey===el.dataset.id);$('dialog').close();formModal('Настройка тарифа','product',`<input type="hidden" name="productKey" value="${h(p.productKey)}">`+field('name','Название',p.name)+field('description','Что входит',p.description,'textarea')+field('amount','Стоимость',p.priceMinor/100)+field('currency','Валюта',p.currency)+field('checkoutUrl','Ссылка оплаты',p.checkoutUrl,'url'));$('f-checkoutUrl').required=false;return;}
    if(name==='billing'){$('dialog').close();await loadDashboard(el.dataset.id||accountId);formModal('Условия сопровождения','billing',selectField('status','Доступ',[['trial_pending','Не активирован'],['trial','Пробный'],['past_due','Ожидается оплата'],['active','Активен'],['complimentary','Без оплаты'],['paused','Приостановлен'],['canceled','Отключён']],account().billing.status)+field('currentPeriodEnd','Действует до',account().billing.currentPeriodEnd?.slice(0,10)||'','date')+field('checkoutUrl','Ссылка оплаты сопровождения',account().billing.checkoutUrl||'','url')+field('extraSiteSlots','Дополнительные сайты',account().billing.extraSiteSlots||0,'number')+selectField('reviewsStatus','Доступ к отзывам',[['trial_pending','Не активирован'],['trial','Пробный'],['past_due','Ожидается оплата'],['active','Активен'],['complimentary','Без оплаты'],['paused','Приостановлен'],['canceled','Отключён']],account().features.reviews.status)+field('reviewsEnd','Отзывы действуют до',account().features.reviews.currentPeriodEnd?.slice(0,10)||'','date'));$('f-reviewsEnd').required=false;$('f-currentPeriodEnd').required=false;$('f-checkoutUrl').required=false;return;}
    if(name==='support-telegram'){const d=await api('/v1/platform/support/status');modal('Уведомления об обращениях',`<p>${d.configured?'Подключены: '+h(d.destination):'Получайте уведомления о новых обращениях и ответах клиентов.'}</p><div class="actions">${d.configured?button('Отправить тест','support-test')+button('Отключить','support-disconnect','',true):button('Подключить','support-connect')}</div>`);return;}
    if(['support-connect','support-test','support-disconnect'].includes(name)){const d=await api('/v1/platform/support/'+name.split('-')[1],'POST',{});$('dialog').close();if(name==='support-connect')modal('Подключить Telegram',external(d.connectUrl,'Открыть бота и нажать Start'));else toast(name==='support-test'?'Тест отправлен.':'Уведомления отключены.');return;}
    if(name==='telegram'){const d=await api(siteApi('/telegram/status'));modal('Telegram-уведомления',`<p>${d.configured?'Уведомления подключены.':'Подключите уведомления о проверках и заявках.'}</p><div class="actions">${d.configured?button('Отправить тест','telegram-test')+button('Отключить','telegram-disconnect','',true):button('Подключить','telegram-connect')}</div>`);return;}
    if(name==='telegram-connect'){const d=await api(siteApi('/telegram/connect'),'POST',{});modal('Подключить Telegram',`<p>Откройте бота и нажмите Start. Затем вернитесь в кабинет.</p><div class="actions">${external(d.connectUrl,'Открыть бота')}</div>`);return;}
    if(name==='telegram-test'||name==='telegram-disconnect'){await api(siteApi('/telegram/'+name.split('-')[1]),'POST',{});toast(name==='telegram-test'?'Тестовое уведомление отправлено.':'Уведомления отключены.');$('dialog').close();await loadDashboard();await render();return;}
    if(name==='metrica-connect'){const d=await api(siteApi('/yandex-metrica/connect'),'POST',{});modal('Подключить Метрику',external(d.authorizeUrl,'Разрешить доступ в Яндексе'));return;}
    if(name==='metrica-disconnect'){formModal('Отключить Метрику','metrica-disconnect','<p>SiteCare перестанет получать статистику. Счётчик на сайте останется.</p>','Отключить');return;}
    if(name==='add-review'||name==='edit-review'){const w=reviews.widgets.find(w=>w.widgetId===el.dataset.id);formModal(w?'Настроить источник':'Подключить отзывы',w?'edit-review':'add-review',`<input type="hidden" name="widgetId" value="${h(w?.widgetId||'')}">`+(w?'':selectField('serviceKey','Источник',reviews.catalog.map(c=>[c.key,c.label]),reviews.catalog[0]?.key))+field('businessIdentifier','Ссылка на организацию',w?.businessIdentifier||'')+selectField('designTemplateKey','Вид блока',[['classic','Карточки'],['spotlight','Один отзыв'],['rows','Компактный список'],['sources','По источникам']],w?.designTemplateKey||'classic')+(w?selectField('enabled','Показывать на сайте',[['1','Да'],['0','Нет']],w.enabled?'1':'0'):''));return;}
  }
  async function submit(form){
    const type=form.dataset.form,b=Object.fromEntries(new FormData(form));
    if(type==='login'){await api('/v1/platform/auth/login','POST',b);await loadDashboard();await render();return;}
    if(type==='new-request'){const d=await api(siteApi('/care'),'POST',b);care=null;$('dialog').close();await openRequest(d.request.request_id);return;}
    if(type==='message'){await actCare('message',{content:b.content});return;}
    if(['answer','quote','accept','payment','complete','cancel'].includes(type)){
      if(type==='quote'){const raw=String(b.amount).replace(',','.').trim();if(!/^\d+(?:\.\d{1,2})?$/.test(raw))throw new Error('Укажите сумму в рублях, не более двух знаков после запятой.');b.amountMinor=Math.round(Number(raw)*100);}
      await actCare(type,b);$('dialog').close();return;
    }
    if(type==='member-role')await api('/v1/platform/accounts/'+accountId+'/members/'+b.userId,'PATCH',{role:b.role});
    if(type==='close-sessions')await api('/v1/platform/operator/accounts/'+accountId+'/users/'+b.userId+'/sessions','POST',{});
    if(type==='member-status')await api('/v1/platform/operator/accounts/'+accountId+'/users/'+b.userId+'/status','PATCH',{status:b.status});
    if(type==='password'){
      await api('/v1/platform/profile/password','POST',b);
      $('dialog').close();state=null;showLogin();toast('Пароль изменён. Войдите снова.');return;
    }
    if(type==='lead')await api('/v1/platform/leads/'+b.leadId,'PATCH',{status:b.status,note:b.note});
    if(type==='add-client'){const d=await api('/v1/platform/operator/accounts','POST',b);$('dialog').close();modal('Приглашение клиенту',`<p>Передайте клиенту одноразовую ссылку. Пароль он установит сам.</p><code class="code">${h(d.inviteUrl)}</code>`);await loadDashboard();await render();return;}
    if(type==='invite'){const d=await api('/v1/platform/accounts/'+accountId+'/invites','POST',b);$('dialog').close();modal('Приглашение',`<code class="code">${h(d.inviteUrl)}</code>`);return;}
    if(type==='add-site'){const d=await api('/v1/platform/accounts/'+accountId+'/sites','POST',{name:b.name,url:b.targetUrl,formRequired:b.formRequired==='1',scope:'site'});$('dialog').close();await loadDashboard();await render();modal('Подключение сайта',`<p>Сохраните адрес приёмщика в Tilda. Он показан только сейчас.</p><code class="code">${h(d.webhookUrl||'Формы не подключены')}</code><p>Остальные настройки — в разделе «Подключения».</p>`);return;}
    if(type==='webhook'){const d=await api(siteApi('/webhook/rotate'),'POST',{});$('dialog').close();modal('Адрес приёмщика форм',`<p>Укажите этот адрес в Tilda, перепубликуйте сайт и проверьте форму.</p><code class="code">${h(d.webhookUrl)}</code>`);return;}
    if(type==='site-settings')await api(siteApi(''),'PATCH',{...b,formRequired:b.formRequired==='1'});
    if(type==='product'){const raw=b.amount.replace(',','.').trim();if(!/^\d+(?:\.\d{1,2})?$/.test(raw))throw new Error('Укажите стоимость с точностью до копеек.');await api('/v1/platform/operator/products','PATCH',{products:[{...b,priceMinor:Math.round(Number(raw)*100)}]});}
    if(type==='billing')await api('/v1/platform/operator/accounts/'+accountId+'/billing','PATCH',{status:b.status,checkoutUrl:b.checkoutUrl,extraSiteSlots:Number(b.extraSiteSlots),currentPeriodEnd:b.currentPeriodEnd?new Date(b.currentPeriodEnd).toISOString():null,features:{reviews:{status:b.reviewsStatus,currentPeriodEnd:b.reviewsEnd?new Date(b.reviewsEnd).toISOString():null}}});
    if(type==='metrica-disconnect')await api(siteApi('/yandex-metrica/disconnect'),'POST',{});
    if(type==='add-review')await api(siteApi('/review-widgets'),'POST',b);
    if(type==='edit-review')await api(siteApi('/review-widgets/'+b.widgetId),'PATCH',{...b,enabled:b.enabled==='1'});
    $('dialog').close();leadRows=[];await loadDashboard();await render();toast('Изменения сохранены.');
  }
  document.addEventListener('click',async event=>{
    const el=event.target.closest('[data-action]');if(!el)return;
    el.disabled=true;try{await action(el.dataset.action,el);}catch(error){toast(error.message);}finally{el.disabled=false;}
  });
  document.addEventListener('submit',async event=>{
    const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();const btn=event.submitter;if(btn)btn.disabled=true;
    try{await submit(form);}catch(error){const target=form.querySelector('#formError')||(form.dataset.form==='login'?$('loginError'):null);if(target){target.hidden=false;target.textContent=error.message;}else toast(error.message);}finally{if(btn)btn.disabled=false;}
  });
  const mobileMenu=matchMedia('(max-width:860px)');
  function syncMenu(){const open=document.body.classList.contains('menu-open');document.querySelector('.sidebar').inert=mobileMenu.matches&&!open;$('scrim').hidden=!mobileMenu.matches||!open;$('menuToggle').setAttribute('aria-expanded',String(mobileMenu.matches?open:!document.body.classList.contains('collapsed')));}
  function closeMenu(){document.body.classList.remove('menu-open');syncMenu();}
  $('menuToggle').addEventListener('click',()=>{document.body.classList.toggle(mobileMenu.matches?'menu-open':'collapsed');syncMenu();});
  $('scrim').addEventListener('click',()=>{closeMenu();$('menuToggle').focus();});
  mobileMenu.addEventListener('change',syncMenu);syncMenu();
  document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();(state?$('view'):$('loginEmail')).focus();});
  $('siteSelect').addEventListener('change',async e=>{try{await switchSite(e.target.value);await render();}catch(err){toast(err.message);}});
  $('logout').addEventListener('click',async()=>{try{await api('/v1/platform/auth/logout','POST',{});state=null;showLogin();}catch(e){toast(e.message);}});
  $('dialogClose').addEventListener('click',()=>$('dialog').close());$('dialog').addEventListener('close',()=>{if(dialogReturnFocus?.isConnected)dialogReturnFocus.focus();});
  let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='findingSearch'){search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{await render();const input=$('findingSearch');input?.focus();},350);}});
  window.addEventListener('hashchange',()=>{filter='all';search='';if(!['work','requests'].includes(view())){selectedRequest='';detail=null;}closeMenu();render();window.scrollTo(0,0);});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();}});
  loadDashboard().then(async()=>{const params=new URL(location.href).searchParams;if(params.get('site')&&params.get('site')!==siteId)await switchSite(params.get('site'));if(params.get('request'))await openRequest(params.get('request'));else await render();}).catch(e=>{showLogin();if(e.status!==401){$('loginError').hidden=false;$('loginError').textContent=e.message;}});
}
